# Create a test for learningService logic
cat <<'EOF' > desktop/src/services/__tests__/learningService.test.ts
import { describe, expect, it } from "vitest";
import { applyFeedback, LearningState, SoundFeedback } from "../learningService";

describe("learningService feedback logic", () => {
    const initialState: LearningState = {
        profileId: "test-profile",
        headphoneId: "test-hp",
        genre: "test-genre",
        learnedGains: new Array(31).fill(0),
        sampleCount: 0,
        updatedAt: 0
    };

    it("applies 'muddy' feedback correctly (low-mid reduction)", () => {
        const after = applyFeedback(initialState, "muddy");
        // Verify low-mid (12-16) are reduced
        for (let i = 12; i <= 16; i++) {
            expect(after.learnedGains[i]).toBeLessThan(0);
        }
        // Verify others are 0
        expect(after.learnedGains[0]).toBe(0);
        expect(after.learnedGains[30]).toBe(0);
    });

    it("applies 'sharp' feedback correctly (upper-mid reduction)", () => {
        const after = applyFeedback(initialState, "sharp");
        // Verify upper-mid/presence (22-26) are reduced
        for (let i = 22; i <= 26; i++) {
            expect(after.learnedGains[i]).toBeLessThan(0);
        }
    });

    it("reinforces state with 'neutral'", () => {
        const after = applyFeedback(initialState, "neutral");
        expect(after.learnedGains).toEqual(initialState.learnedGains);
        expect(after.sampleCount).toBe(initialState.sampleCount + 1);
    });
});
EOF
npx vitest run desktop/src/services/__tests__/learningService.test.ts
